import base64
import json
import zlib

from django.core.management.base import BaseCommand
from menu.models import MenuItem


_DATA = """"""
TRANSLATIONS = json.loads(zlib.decompress(base64.b64decode(_DATA)).decode("utf-8"))


class Command(BaseCommand):
    help = "Populate English descriptions for all translated menu items."

    def handle(self, *args, **options):
        updated = 0
        unchanged = 0
        missing = []

        for slug, description_en in TRANSLATIONS.items():
            try:
                item = MenuItem.objects.get(slug=slug)
            except MenuItem.DoesNotExist:
                missing.append(slug)
                continue

            if item.description_en == description_en:
                unchanged += 1
                continue

            item.description_en = description_en
            item.save(update_fields=["description_en"])
            updated += 1
            self.stdout.write(self.style.SUCCESS(f"UPDATED: {slug}"))

        self.stdout.write("")
        self.stdout.write(self.style.SUCCESS(f"Updated {updated} item(s)."))
        self.stdout.write(f"Already correct: {unchanged} item(s).")

        if missing:
            self.stdout.write(self.style.WARNING(
                "Missing slugs: " + ", ".join(missing)
            ))
